using System.Collections.Generic;
using UnityEngine;
using Starline.Battle;

namespace Starline.Client
{
    /// <summary>
    /// Background music. Which track plays where comes from Resources/StarlineMusic/music.json;
    /// the clips are the .ogg files next to it (generated by tools/music/compose.py). Loops
    /// crossfade between two sources; short stingers (victory / defeat) play on a third one
    /// while the loop fades out.
    /// </summary>
    public sealed class MusicPlayer : MonoBehaviour
    {
        public const string ResourceFolder = "StarlineMusic";
        private const string VolumeKey = "Starline.MusicVolume";

        private readonly Dictionary<string, string> _routes = new Dictionary<string, string>();
        private readonly Dictionary<string, AudioClip> _clips = new Dictionary<string, AudioClip>();
        private AudioSource[] _loops;
        private AudioSource _stinger;
        private int _active;
        private string _current;
        private float _fadeSeconds = 1.5f;
        private float _volume = 0.7f;

        public static MusicPlayer Create(Transform parent)
        {
            var go = new GameObject("Music");
            go.transform.SetParent(parent, false);
            MusicPlayer player = go.AddComponent<MusicPlayer>();
            player.Init();
            return player;
        }

        /// <summary>Music volume 0..1, kept between sessions.</summary>
        public float Volume
        {
            get => _volume;
            set
            {
                _volume = Mathf.Clamp01(value);
                PlayerPrefs.SetFloat(VolumeKey, _volume);
                _stinger.volume = _volume;
            }
        }

        private void Init()
        {
            _loops = new[] { NewSource(true), NewSource(true) };
            _stinger = NewSource(false);
            LoadConfig();
            _volume = PlayerPrefs.GetFloat(VolumeKey, _volume);
            _stinger.volume = _volume;
        }

        private AudioSource NewSource(bool loop)
        {
            AudioSource source = gameObject.AddComponent<AudioSource>();
            source.loop = loop;
            source.playOnAwake = false;
            source.spatialBlend = 0f;
            source.volume = 0f;
            return source;
        }

        private void LoadConfig()
        {
            TextAsset asset = Resources.Load<TextAsset>(ResourceFolder + "/music");
            if (asset == null)
            {
                Debug.LogWarning("Starline：找不到 " + ResourceFolder + "/music.json，背景音乐关闭。");
                return;
            }
            JsonValue root = Json.Parse(asset.text, "music.json");
            _fadeSeconds = root.FixValue("fadeSeconds", Fix.FromRatio(3, 2)).ToFloat();
            _volume = root.FixValue("volume", Fix.FromRatio(7, 10)).ToFloat();
            foreach (string section in new[] { "screens", "stingers", "battle", "acts", "terrains" })
            {
                JsonValue table = root.Get(section);
                if (table == null || table.Kind != JsonKind.Object)
                {
                    continue;
                }
                foreach (KeyValuePair<string, JsonValue> entry in table.Members)
                {
                    _routes[section + "." + entry.Key] = entry.Value.AsString();
                }
            }
        }

        /// <summary>The track for a route like "screens.menu", or null.</summary>
        private string Route(string key) => _routes.TryGetValue(key, out string track) ? track : null;

        /// <summary>Plays the loop configured for a screen (music.json → screens).</summary>
        public void PlayScreen(string screen) => Play(Route("screens." + screen));

        /// <summary>
        /// Battle music: boss tracks first, then the battlefield environment (once encounters
        /// carry a terrain id), then the act, then the default.
        /// </summary>
        public void PlayBattle(bool boss, bool finalBoss, string actId, string terrainId = null)
        {
            string track = null;
            if (finalBoss)
            {
                track = Route("battle.finalBoss");
            }
            if (track == null && boss)
            {
                track = Route("battle.boss");
            }
            if (track == null && !string.IsNullOrEmpty(terrainId))
            {
                track = Route("terrains." + terrainId);
            }
            if (track == null && !string.IsNullOrEmpty(actId))
            {
                track = Route("acts." + actId);
            }
            Play(track ?? Route("battle.default"));
        }

        /// <summary>A one-shot (music.json → stingers); the current loop fades out under it.</summary>
        public void PlayStinger(string key)
        {
            AudioClip clip = Clip(Route("stingers." + key));
            Play(null);
            if (clip != null)
            {
                _stinger.clip = clip;
                _stinger.volume = _volume;
                _stinger.Play();
            }
        }

        /// <summary>Crossfades to a loop by track id; null fades out. The same id keeps playing.</summary>
        public void Play(string track)
        {
            if (track == _current)
            {
                return;
            }
            _current = track;
            AudioClip clip = Clip(track);
            if (clip == null)
            {
                return;
            }
            _active = 1 - _active;
            AudioSource next = _loops[_active];
            next.clip = clip;
            next.volume = 0f;
            next.Play();
        }

        private AudioClip Clip(string track)
        {
            if (string.IsNullOrEmpty(track))
            {
                return null;
            }
            if (!_clips.TryGetValue(track, out AudioClip clip))
            {
                clip = Resources.Load<AudioClip>(ResourceFolder + "/" + track);
                if (clip == null)
                {
                    Debug.LogWarning("Starline：找不到音乐 " + ResourceFolder + "/" + track);
                }
                _clips[track] = clip;
            }
            return clip;
        }

        private void Update()
        {
            float step = _fadeSeconds > 0f ? Time.unscaledDeltaTime / _fadeSeconds : 1f;
            bool silent = _current == null || Clip(_current) == null;
            // Hold the new loop down while a stinger is still sounding.
            float target = silent ? 0f : _stinger.isPlaying ? _volume * 0.25f : _volume;
            for (int i = 0; i < _loops.Length; i++)
            {
                AudioSource source = _loops[i];
                float goal = i == _active ? target : 0f;
                source.volume = Mathf.MoveTowards(source.volume, goal, step * Mathf.Max(_volume, 0.01f));
                if (i != _active && source.isPlaying && source.volume <= 0f)
                {
                    source.Stop();
                    source.clip = null;
                }
            }
        }
    }
}
